from rdkit import Chem
from rdkit.Chem import AllChem
s='n1c(CN=C(Nc2c(C)cccc2C)C)cccc1'
m=Chem.AddHs(Chem.MolFromSmiles(s))
print(Chem.MolToSmiles(m))
for a in m.GetAtoms():
 if a.GetSymbol()=='N': print(a.GetIdx(),a.GetIsAromatic(),a.GetHybridization(),[(n.GetIdx(),n.GetSymbol()) for n in a.GetNeighbors()])
p=AllChem.ETKDGv3(); p.randomSeed=19
print(AllChem.EmbedMolecule(m,p))
print(AllChem.MMFFOptimizeMolecule(m))
conf=m.GetConformer()
import numpy as np
ns=[a.GetIdx() for a in m.GetAtoms() if a.GetSymbol()=='N']
for i in ns: print('N',i,conf.GetAtomPosition(i))
for i in range(len(ns)):
 for j in range(i): print('dist',ns[i],ns[j],np.linalg.norm(np.array(conf.GetAtomPosition(ns[i]))-np.array(conf.GetAtomPosition(ns[j]))))

